from fastapi import APIRouter, Depends
from sqlalchemy.orm import Session
from sqlalchemy import or_, func
import re
from ..database import get_db
from ..models import Employee, Seat, SeatAllocation, Project, User
from ..schemas import AssistantQuery, AssistantResponse
from ..auth import get_current_user

router = APIRouter(prefix="/ai", tags=["ai"])


def parse_query_intent(query: str) -> dict:
    """Rule-based intent parser"""
    query_lower = query.lower()

    intent = {
        "type": "unknown",
        "entities": {}
    }

    # Extract email patterns
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    emails = re.findall(email_pattern, query)
    if emails:
        intent["entities"]["email"] = emails[0]

    # Extract employee name patterns (basic heuristic)
    name_patterns = [
        r"employee\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)",
        r"person\s+named\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)",
        r"([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)'s\s+seat",
        r"where\s+(?:does\s+)?([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)\s+sit",
    ]
    for pattern in name_patterns:
        match = re.search(pattern, query)
        if match:
            intent["entities"]["name"] = match.group(1)
            break

    # Extract project names
    project_keywords = ["indigo", "indreed", "mydreed", "preed", "serfy", "oreed", "bedegreed", "opreed", "serry", "kaary", "mered", "talos"]
    for proj in project_keywords:
        if proj in query_lower:
            intent["entities"]["project"] = proj.capitalize()
            break

    # Extract floor numbers
    floor_match = re.search(r'floor\s+(\d+)', query_lower)
    if floor_match:
        intent["entities"]["floor"] = int(floor_match.group(1))

    # Detect intent type
    if any(keyword in query_lower for keyword in ["where", "seat", "sits", "sitting", "located"]):
        if "email" in intent["entities"] or "name" in intent["entities"]:
            intent["type"] = "employee_seat_lookup"
        elif "project" in intent["entities"]:
            intent["type"] = "project_seat_lookup"
    elif any(keyword in query_lower for keyword in ["project", "assigned", "working on"]):
        if "email" in intent["entities"] or "name" in intent["entities"]:
            intent["type"] = "employee_project_lookup"
    elif any(keyword in query_lower for keyword in ["available", "free", "vacant"]):
        intent["type"] = "available_seats"
    elif any(keyword in query_lower for keyword in ["utilization", "occupancy", "usage", "dashboard"]):
        intent["type"] = "utilization"
    elif "my seat" in query_lower or "i sit" in query_lower:
        intent["type"] = "my_seat_lookup"

    return intent


def handle_employee_seat_lookup(intent: dict, db: Session) -> str:
    """Find where an employee sits"""
    if "email" in intent["entities"]:
        employee = db.query(Employee).filter(Employee.email == intent["entities"]["email"]).first()
    elif "name" in intent["entities"]:
        name = intent["entities"]["name"]
        employee = db.query(Employee).filter(Employee.name.ilike(f"%{name}%")).first()
    else:
        return "I couldn't identify which employee you're asking about. Please provide a name or email."

    if not employee:
        return "I couldn't find that employee in the system."

    # Get active allocation
    allocation = db.query(SeatAllocation).filter(
        SeatAllocation.employee_id == employee.id,
        SeatAllocation.allocation_status == "active"
    ).first()

    if not allocation:
        return f"{employee.name} ({employee.email}) does not currently have an assigned seat. Status: {employee.status}"

    seat = db.query(Seat).filter(Seat.id == allocation.seat_id).first()
    project = db.query(Project).filter(Project.id == employee.project_id).first()

    return f"{employee.name} sits at seat {seat.seat_number} on Floor {seat.floor}, Zone {seat.zone}, Bay {seat.bay}. They are assigned to the {project.name} project."


def handle_employee_project_lookup(intent: dict, db: Session) -> str:
    """Find what project an employee is on"""
    if "email" in intent["entities"]:
        employee = db.query(Employee).filter(Employee.email == intent["entities"]["email"]).first()
    elif "name" in intent["entities"]:
        name = intent["entities"]["name"]
        employee = db.query(Employee).filter(Employee.name.ilike(f"%{name}%")).first()
    else:
        return "I couldn't identify which employee you're asking about. Please provide a name or email."

    if not employee:
        return "I couldn't find that employee in the system."

    project = db.query(Project).filter(Project.id == employee.project_id).first()
    return f"{employee.name} is assigned to the {project.name} project."


def handle_available_seats(intent: dict, db: Session) -> str:
    """List available seats"""
    query = db.query(Seat).filter(Seat.status == "available")

    if "floor" in intent["entities"]:
        floor = intent["entities"]["floor"]
        query = query.filter(Seat.floor == floor)
        seats = query.all()
        if not seats:
            return f"There are no available seats on floor {floor}."
        return f"There are {len(seats)} available seats on floor {floor}: " + ", ".join([s.seat_number for s in seats[:10]]) + ("..." if len(seats) > 10 else "")
    else:
        total = query.count()
        if total == 0:
            return "There are no available seats at the moment."

        # Group by floor
        floor_counts = db.query(Seat.floor, func.count(Seat.id)).filter(
            Seat.status == "available"
        ).group_by(Seat.floor).all()

        floor_breakdown = ", ".join([f"Floor {f}: {c} seats" for f, c in floor_counts])
        return f"There are {total} available seats total. Breakdown: {floor_breakdown}"


def handle_project_seat_lookup(intent: dict, db: Session) -> str:
    """Find where a project's team sits"""
    project_name = intent["entities"].get("project", "").capitalize()
    project = db.query(Project).filter(Project.name.ilike(f"%{project_name}%")).first()

    if not project:
        return f"I couldn't find a project matching '{project_name}'."

    # Get active allocations for this project
    allocations = db.query(SeatAllocation, Seat).join(
        Seat, SeatAllocation.seat_id == Seat.id
    ).filter(
        SeatAllocation.project_id == project.id,
        SeatAllocation.allocation_status == "active"
    ).all()

    if not allocations:
        return f"The {project.name} project currently has no allocated seats."

    # Group by floor and zone
    floor_zone_counts = {}
    for allocation, seat in allocations:
        key = (seat.floor, seat.zone)
        floor_zone_counts[key] = floor_zone_counts.get(key, 0) + 1

    breakdown = ", ".join([
        f"Floor {floor} Zone {zone}: {count} seats"
        for (floor, zone), count in sorted(floor_zone_counts.items())
    ])

    return f"The {project.name} project has {len(allocations)} team members with allocated seats. Distribution: {breakdown}"


def handle_utilization(intent: dict, db: Session) -> str:
    """Provide utilization stats"""
    total_seats = db.query(Seat).count()
    occupied = db.query(Seat).filter(Seat.status == "occupied").count()
    available = db.query(Seat).filter(Seat.status == "available").count()
    reserved = db.query(Seat).filter(Seat.status == "reserved").count()
    maintenance = db.query(Seat).filter(Seat.status == "maintenance").count()

    utilization_pct = (occupied / total_seats * 100) if total_seats > 0 else 0

    return f"Current seat utilization: {utilization_pct:.1f}% ({occupied}/{total_seats} seats occupied). Available: {available}, Reserved: {reserved}, Maintenance: {maintenance}."


@router.post("/query", response_model=AssistantResponse)
def query_assistant(
    request: AssistantQuery,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    """Natural language assistant endpoint"""
    intent = parse_query_intent(request.query)

    answer = ""

    if intent["type"] == "employee_seat_lookup":
        answer = handle_employee_seat_lookup(intent, db)
    elif intent["type"] == "employee_project_lookup":
        answer = handle_employee_project_lookup(intent, db)
    elif intent["type"] == "available_seats":
        answer = handle_available_seats(intent, db)
    elif intent["type"] == "project_seat_lookup":
        answer = handle_project_seat_lookup(intent, db)
    elif intent["type"] == "utilization":
        answer = handle_utilization(intent, db)
    elif intent["type"] == "my_seat_lookup":
        # If user has an employee record linked
        if current_user.employee_id:
            intent["entities"]["email"] = current_user.email
            answer = handle_employee_seat_lookup(intent, db)
        else:
            answer = "I couldn't find an employee record linked to your account."
    else:
        answer = "I'm not sure how to help with that. Try asking:\n- Where does [name/email] sit?\n- What project is [name/email] on?\n- Which seats are available on floor [number]?\n- Where does the [project name] team sit?\n- What is the current seat utilization?"

    return AssistantResponse(answer=answer, query=request.query)

