import type { Employee, Project, Seat, Dashboard, SeatAllocation, SeatSuggestion, User } from './types';

const API_BASE = '/api';

class APIError extends Error {
  constructor(public status: number, message: string) {
    super(message);
    this.name = 'APIError';
  }
}

async function fetchAPI<T>(
  endpoint: string,
  options: RequestInit = {}
): Promise<T> {
  const token = localStorage.getItem('auth_token');

  const headers: HeadersInit = {
    'Content-Type': 'application/json',
    ...options.headers,
  };

  if (token && !endpoint.includes('/auth/login')) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  const response = await fetch(`${API_BASE}${endpoint}`, {
    ...options,
    headers,
  });

  if (response.status === 401 || response.status === 403) {
    // Token expired or unauthorized
    localStorage.removeItem('auth_token');
    localStorage.removeItem('user_email');
    localStorage.removeItem('user_role');

    if (window.location.pathname !== '/login') {
      window.location.href = `/login?next=${encodeURIComponent(window.location.pathname)}`;
    }

    throw new APIError(response.status, 'Unauthorized');
  }

  if (!response.ok) {
    let errorMessage = `HTTP error ${response.status}`;
    try {
      const errorData = await response.json();
      errorMessage = errorData.detail || errorMessage;
    } catch {
      // Ignore JSON parse errors
    }
    throw new APIError(response.status, errorMessage);
  }

  if (response.status === 204) {
    return {} as T;
  }

  return response.json();
}

export const api = {
  // Auth
  async login(email: string, password: string) {
    const data = await fetchAPI<{ access_token: string; token_type: string }>(
      '/auth/login',
      {
        method: 'POST',
        body: JSON.stringify({ email, password }),
      }
    );
    return data;
  },

  // Employees
  async getEmployees(params?: {
    search?: string;
    project_id?: number;
    floor?: number;
    zone?: string;
    status?: string;
    seat_status?: string;
  }) {
    const query = new URLSearchParams();
    if (params?.search) query.append('search', params.search);
    if (params?.project_id) query.append('project_id', params.project_id.toString());
    if (params?.floor) query.append('floor', params.floor.toString());
    if (params?.zone) query.append('zone', params.zone);
    if (params?.status) query.append('status', params.status);
    if (params?.seat_status) query.append('seat_status', params.seat_status);

    return fetchAPI<Employee[]>(`/employees?${query}`);
  },

  async getEmployee(id: number) {
    return fetchAPI<Employee>(`/employees/${id}`);
  },

  async createEmployee(data: {
    name: string;
    email: string;
    department: string;
    role: string;
    joining_date: string;
    project_id: number;
  }) {
    return fetchAPI<Employee>('/employees', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  async updateEmployee(id: number, data: Partial<Employee>) {
    return fetchAPI<Employee>(`/employees/${id}`, {
      method: 'PATCH',
      body: JSON.stringify(data),
    });
  },

  // Projects
  async getProjects() {
    return fetchAPI<Project[]>('/projects');
  },

  // Seats
  async getSeats(params?: { floor?: number; zone?: string; status?: string }) {
    const query = new URLSearchParams();
    if (params?.floor) query.append('floor', params.floor.toString());
    if (params?.zone) query.append('zone', params.zone);
    if (params?.status) query.append('status', params.status);

    return fetchAPI<Seat[]>(`/seats?${query}`);
  },

  async getAvailableSeats(params?: { floor?: number; zone?: string }) {
    const query = new URLSearchParams();
