import { useQuery } from '@tanstack/react-query';
import { useNavigate } from 'react-router-dom';
import { api } from '../lib/api';

export default function Dashboard() {
  const navigate = useNavigate();
  const { data: dashboard, isLoading } = useQuery({
    queryKey: ['dashboard'],
    queryFn: () => api.getDashboard(),
  });

  if (isLoading) {
    return <div className="text-center py-12">Loading dashboard...</div>;
  }

  if (!dashboard) {
    return <div className="text-center py-12">Failed to load dashboard</div>;
  }

  const metrics = [
    {
      label: 'Total Employees',
      value: dashboard.total_employees.toLocaleString(),
      color: 'text-blue-600',
    },
    {
      label: 'Total Seats',
      value: dashboard.total_seats.toLocaleString(),
      color: 'text-gray-600',
    },
    {
      label: 'Occupied',
      value: dashboard.occupied_seats.toLocaleString(),
      color: 'text-gray-600',
    },
    {
      label: 'Available',
      value: dashboard.available_seats.toLocaleString(),
      color: 'text-green-600',
    },
    {
      label: 'Reserved',
      value: dashboard.reserved_seats.toLocaleString(),
      color: 'text-amber-600',
    },
    {
      label: 'Pending Allocation',
      value: dashboard.pending_allocation_count.toLocaleString(),
      color: 'text-red-600',
      clickable: true,
      onClick: () => navigate('/employees?seat_status=pending'),
    },
  ];

  const utilizationPercent = ((dashboard.occupied_seats / dashboard.total_seats) * 100).toFixed(1);

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-bold">Dashboard</h1>
        <p className="text-gray-500 mt-1">Overview of seat allocation and utilization</p>
      </div>

      {/* Metrics Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
        {metrics.map((metric) => (
          <div
            key={metric.label}
            onClick={metric.clickable ? metric.onClick : undefined}
            className={`bg-white dark:bg-gray-800 rounded-xl p-6 shadow ${
              metric.clickable ? 'cursor-pointer hover:shadow-lg transition-default' : ''
            }`}
          >
            <div className="text-sm text-gray-500 mb-2">{metric.label}</div>
            <div className={`text-3xl font-bold tabular-nums ${metric.color}`}>
              {metric.value}
            </div>
          </div>
        ))}
      </div>

      {/* Utilization */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow">
        <h2 className="text-xl font-semibold mb-4">Seat Utilization</h2>
        <div className="flex items-center gap-4">
          <div className="text-5xl font-bold text-primary tabular-nums">{utilizationPercent}%</div>
          <div className="text-gray-500">
            {dashboard.occupied_seats.toLocaleString()} of {dashboard.total_seats.toLocaleString()}{' '}
            seats occupied
          </div>
        </div>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow">
          <h2 className="text-xl font-semibold mb-4">Seat Status Breakdown</h2>
          <div className="space-y-3">
            {[
              { label: 'Occupied', value: dashboard.occupied_seats, color: 'bg-gray-500' },
              { label: 'Available', value: dashboard.available_seats, color: 'bg-green-500' },
              { label: 'Reserved', value: dashboard.reserved_seats, color: 'bg-amber-500' },
              { label: 'Maintenance', value: dashboard.maintenance_seats, color: 'bg-red-500' },
            ].map((item) => (
              <div key={item.label} className="flex items-center gap-3">
                <div className={`w-3 h-3 rounded-full ${item.color}`} />
                <div className="flex-1">{item.label}</div>
                <div className="font-semibold tabular-nums">{item.value.toLocaleString()}</div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow">
          <h2 className="text-xl font-semibold mb-4">Quick Actions</h2>
          <div className="space-y-3">
            <button
              onClick={() => navigate('/employees')}
              className="w-full text-left px-4 py-3 bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 rounded-lg transition-default"
            >
              View All Employees
            </button>
            <button
              onClick={() => navigate('/seats?status=available')}
              className="w-full text-left px-4 py-3 bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 rounded-lg transition-default"
            >
              Browse Available Seats
            </button>
            <button
              onClick={() => navigate('/assistant')}
              className="w-full text-left px-4 py-3 bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 rounded-lg transition-default"
            >
              Ask the Assistant
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

