import { useQuery } from '@tanstack/react-query';
import { useNavigate } from 'react-router-dom';
import { api } from '../lib/api';

export default function Dashboard() {
  const navigate = useNavigate();
  const { data: dashboard, isLoading } = useQuery({
    queryKey: ['dashboard'],
    queryFn: () => api.getDashboard(),
  });

  if (isLoading) {
    return <div className="text-center py-12">Loading dashboard...</div>;
  }

  if (!dashboard) {
    return <div className="text-center py-12">Failed to load dashboard</div>;
  }

  const metrics = [
    {
      label: 'Total Employees',
      value: dashboard.total_employees.toLocaleString(),
      color: 'text-blue-600',
    },
    {
      label: 'Total Seats',
      value: dashboard.total_seats.toLocaleString(),
      color: 'text-gray-600',
    },
    {
      label: 'Occupied',
      value: dashboard.occupied_seats.toLocaleString(),
      color: 'text-gray-600',
    },
    {
      label: 'Available',
      value: dashboard.available_seats.toLocaleString(),
      color: 'text-green-600',
    },
    {
      label: 'Reserved',
      value: dashboard.reserved_seats.toLocaleString(),
      color: 'text-amber-600',
    },
    {
      label: 'Pending Allocation',
      value: dashboard.pending_allocation_count.toLocaleString(),
      color: 'text-red-600',
      clickable: true,
      onClick: () => navigate('/employees?seat_status=pending'),
    },
  ];

  const utilizationPercent = ((dashboard.occupied_seats / dashboard.total_seats) * 100).toFixed(1);

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-bold">Dashboard</h1>
        <p className="text-gray-500 mt-1">Overview of seat allocation and utilization</p>
