import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuth } from '../contexts/AuthContext';
import { api } from '../lib/api';
import type { Seat, Employee, SeatSuggestion } from '../lib/types';

export default function Seats() {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [filters, setFilters] = useState<{ floor?: number; zone?: string; status?: string }>({});
  const [allocateModal, setAllocateModal] = useState<{ seat?: Seat; employee?: Employee } | null>(
    null
  );

  const { data: seats, isLoading } = useQuery({
    queryKey: ['seats', filters],
    queryFn: () => api.getSeats(filters),
  });

  const { data: employees } = useQuery({
    queryKey: ['employees'],
    queryFn: () => api.getEmployees(),
  });

  const releaseMutation = useMutation({
    mutationFn: (employeeId: number) => api.releaseSeat(employeeId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['seats'] });
      queryClient.invalidateQueries({ queryKey: ['employees'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
    },
  });

  if (isLoading) {
    return <div className="text-center py-12">Loading seats...</div>;
  }

  const isAdmin = user?.role === 'admin';
  const pendingEmployees = employees?.filter((e) => e.seat_allocation_status === 'pending') || [];

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Seats</h1>
          <p className="text-gray-500 mt-1">{seats?.length || 0} seats</p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex gap-4">
        <select
          value={filters.floor || ''}
          onChange={(e) => setFilters({ ...filters, floor: e.target.value ? Number(e.target.value) : undefined })}
          className="px-4 py-2 border rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="">All Floors</option>
          {[1, 2, 3, 4, 5].map((f) => (
            <option key={f} value={f}>
              Floor {f}
            </option>
          ))}
        </select>

        <select
          value={filters.zone || ''}
          onChange={(e) => setFilters({ ...filters, zone: e.target.value || undefined })}
          className="px-4 py-2 border rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="">All Zones</option>
          <option value="A">Zone A</option>
          <option value="B">Zone B</option>
        </select>

        <select
          value={filters.status || ''}
          onChange={(e) => setFilters({ ...filters, status: e.target.value || undefined })}
          className="px-4 py-2 border rounded-lg bg-white dark:bg-gray-800"
        >
          <option value="">All Statuses</option>
          <option value="available">Available</option>
          <option value="occupied">Occupied</option>
          <option value="reserved">Reserved</option>
          <option value="maintenance">Maintenance</option>
        </select>
      </div>

      {/* Table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow overflow-hidden">
        <table className="w-full">
          <thead className="bg-gray-50 dark:bg-gray-700 text-left">
            <tr>
              <th className="px-6 py-3 text-sm font-semibold">Seat Number</th>
              <th className="px-6 py-3 text-sm font-semibold">Floor</th>
              <th className="px-6 py-3 text-sm font-semibold">Zone</th>
              <th className="px-6 py-3 text-sm font-semibold">Bay</th>
              <th className="px-6 py-3 text-sm font-semibold">Status</th>
              <th className="px-6 py-3 text-sm font-semibold">Occupant</th>
              {isAdmin && <th className="px-6 py-3 text-sm font-semibold">Actions</th>}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
            {seats?.map((seat) => (
              <tr key={seat.id} className="hover:bg-gray-50 dark:hover:bg-gray-700">
                <td className="px-6 py-4 font-mono text-sm">{seat.seat_number}</td>
                <td className="px-6 py-4">{seat.floor}</td>
                <td className="px-6 py-4">{seat.zone}</td>
                <td className="px-6 py-4">{seat.bay}</td>
                <td className="px-6 py-4">
                  <span
                    className={`px-2 py-1 rounded-full text-xs font-medium ${
                      seat.status === 'available'
                        ? 'bg-green-100 text-green-700'
                        : seat.status === 'occupied'
                        ? 'bg-gray-100 text-gray-700'
                        : seat.status === 'reserved'
                        ? 'bg-amber-100 text-amber-700'
                        : 'bg-red-100 text-red-700'
                    }`}
                  >
                    {seat.status}
                  </span>
                </td>
                <td className="px-6 py-4 text-sm">
                  {seat.employee_name ? (
                    <div>
                      <div>{seat.employee_name}</div>
                      <div className="text-xs text-gray-500 font-mono">{seat.employee_code}</div>
                    </div>
                  ) : (
                    <span className="text-gray-400">-</span>
                  )}
                </td>
                {isAdmin && (
                  <td className="px-6 py-4">
                    {seat.status === 'available' && pendingEmployees.length > 0 && (
                      <button
                        onClick={() => setAllocateModal({ seat })}
                        className="text-sm text-primary hover:underline"
                      >
                        Allocate
                      </button>
                    )}
                    {seat.status === 'occupied' && seat.employee_code && (
                      <button
                        onClick={() => {
                          const emp = employees?.find((e) => e.employee_code === seat.employee_code);
                          if (emp && confirm(`Release seat ${seat.seat_number}?`)) {
                            releaseMutation.mutate(emp.id);
                          }
                        }}
                        className="text-sm text-red-600 hover:underline"
                      >
                        Release
                      </button>
                    )}
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {allocateModal && employees && (
        <AllocateModal
          seat={allocateModal.seat}
          employee={allocateModal.employee}
          employees={pendingEmployees}
          onClose={() => setAllocateModal(null)}
        />
      )}
    </div>
  );
}

function AllocateModal({
  seat,
  employee,
  employees,
  onClose,
}: {
  seat?: Seat;
  employee?: Employee;
  employees: Employee[];
  onClose: () => void;
}) {
  const queryClient = useQueryClient();
  const [selectedEmployeeId, setSelectedEmployeeId] = useState<number>(employee?.id || employees[0]?.id || 0);
  const [suggestions, setSuggestions] = useState<SeatSuggestion[]>([]);
  const [selectedSeatId, setSelectedSeatId] = useState<number | null>(seat?.id || null);

  const allocateMutation = useMutation({
    mutationFn: ({ empId, seatId }: { empId: number; seatId?: number }) =>
      api.allocateSeat(empId, seatId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['seats'] });
      queryClient.invalidateQueries({ queryKey: ['employees'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      onClose();
    },
  });

  const loadSuggestions = async (empId: number) => {
    const sugg = await api.getSeatSuggestions(empId);
    setSuggestions(sugg);
    if (!seat && sugg.length > 0) {
      setSelectedSeatId(sugg[0].id);
    }
  };

  const handleAllocate = () => {
    allocateMutation.mutate({
      empId: selectedEmployeeId,
      seatId: selectedSeatId || undefined,
    });
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
      <div className="bg-white dark:bg-gray-800 rounded-xl max-w-2xl w-full p-6">
        <h2 className="text-2xl font-bold mb-6">Allocate Seat</h2>

        <div className="space-y-4">
          {!employee && (
            <div>
              <label className="block text-sm font-medium mb-2">Employee</label>
              <select
                value={selectedEmployeeId}
                onChange={(e) => {
                  const id = Number(e.target.value);
                  setSelectedEmployeeId(id);
                  loadSuggestions(id);
                }}
                className="w-full px-4 py-2 border rounded-lg bg-white dark:bg-gray-700"
              >
                {employees.map((e) => (
                  <option key={e.id} value={e.id}>
                    {e.name} ({e.employee_code}) - {e.project_name}
                  </option>
                ))}
              </select>
            </div>
          )}

          {!seat && suggestions.length > 0 && (
            <div>
              <label className="block text-sm font-medium mb-2">Suggested Seats</label>
              <div className="space-y-2 max-h-64 overflow-auto">
                {suggestions.slice(0, 10).map((s) => (
                  <button
                    key={s.id}
                    onClick={() => setSelectedSeatId(s.id)}
                    className={`w-full text-left p-3 border rounded-lg transition-default ${
                      selectedSeatId === s.id
                        ? 'border-primary bg-primary/10'
                        : 'border-gray-200 hover:border-gray-300'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <div>
                        <div className="font-mono font-semibold">{s.seat_number}</div>
                        <div className="text-sm text-gray-500">
                          Floor {s.floor}, Zone {s.zone}, Bay {s.bay}
                        </div>
                        {s.reason && <div className="text-xs text-gray-400 mt-1">{s.reason}</div>}
                      </div>
                      {s.is_fallback && (
                        <span className="text-xs text-amber-600 bg-amber-100 px-2 py-1 rounded">
                          Fallback
                        </span>
                      )}
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}

          {seat && (
            <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
              <div className="font-semibold">Seat: {seat.seat_number}</div>
              <div className="text-sm text-gray-500">
                Floor {seat.floor}, Zone {seat.zone}, Bay {seat.bay}
              </div>
            </div>
          )}

          {allocateMutation.error && (
            <div className="text-sm text-red-600">{(allocateMutation.error as any).message}</div>
          )}

          <div className="flex justify-end gap-3 mt-6">
            <button
              onClick={onClose}
              className="px-4 py-2 text-gray-700 hover:bg-gray-100 dark:text-gray-300 dark:hover:bg-gray-700 rounded-lg transition-default"
            >
              Cancel
            </button>
            <button
              onClick={handleAllocate}
              disabled={allocateMutation.isPending || !selectedSeatId}
              className="px-4 py-2 bg-primary hover:bg-primary-hover text-white rounded-lg transition-default disabled:opacity-50"
            >
              {allocateMutation.isPending ? 'Allocating...' : 'Allocate'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

