import { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { api } from '../lib/api';

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

export default function Assistant() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');

  const queryMutation = useMutation({
    mutationFn: (query: string) => api.queryAssistant(query),
    onSuccess: (data) => {
      setMessages((prev) => [...prev, { role: 'assistant', content: data.answer }]);
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    setMessages((prev) => [...prev, { role: 'user', content: input }]);
    queryMutation.mutate(input);
    setInput('');
  };

  const exampleQueries = [
    "Where does amit@ethara.ai sit?",
    "What project is Amit on?",
    "Which seats are available on floor 2?",
    "Where does the Talos team sit?",
    "What is the current seat utilization?",
  ];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold">AI Assistant</h1>
        <p className="text-gray-500 mt-1">Ask questions about employees, seats, and projects</p>
      </div>

      {messages.length === 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow p-6">
          <h2 className="text-lg font-semibold mb-4">Example Queries</h2>
          <div className="space-y-2">
            {exampleQueries.map((query, idx) => (
              <button
                key={idx}
                onClick={() => {
                  setInput(query);
                }}
                className="w-full text-left px-4 py-3 bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 rounded-lg text-sm transition-default"
              >
                {query}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Messages */}
      <div className="space-y-4">
        {messages.map((msg, idx) => (
          <div
            key={idx}
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-2xl px-6 py-4 rounded-xl ${
                msg.role === 'user'
                  ? 'bg-primary text-white'
                  : 'bg-white dark:bg-gray-800 shadow'
              }`}
            >
              <div className="text-sm whitespace-pre-wrap">{msg.content}</div>
            </div>
          </div>
        ))}
        {queryMutation.isPending && (
          <div className="flex justify-start">
            <div className="bg-white dark:bg-gray-800 shadow px-6 py-4 rounded-xl">
              <div className="text-sm text-gray-500">Thinking...</div>
            </div>
          </div>
        )}
      </div>

      {/* Input */}
      <form onSubmit={handleSubmit} className="sticky bottom-0 bg-gray-50 dark:bg-gray-900 py-4">
        <div className="flex gap-3">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Ask a question..."
            className="flex-1 px-4 py-3 border rounded-lg focus:ring-2 focus:ring-primary bg-white dark:bg-gray-800"
          />
          <button
            type="submit"
            disabled={!input.trim() || queryMutation.isPending}
            className="px-6 py-3 bg-primary hover:bg-primary-hover text-white rounded-lg transition-default disabled:opacity-50"
          >
            Send
          </button>
        </div>
      </form>
    </div>
  );
}

