import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '../lib/api';

export default function Import() {
  const queryClient = useQueryClient();
  const [file, setFile] = useState<File | null>(null);
  const [result, setResult] = useState<{
    imported: number;
    skipped: number;
    errors: string[];
  } | null>(null);

  const importMutation = useMutation({
    mutationFn: (file: File) => api.importCSV(file),
    onSuccess: (data) => {
      setResult(data);
      queryClient.invalidateQueries({ queryKey: ['employees'] });
      queryClient.invalidateQueries({ queryKey: ['seats'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (file) {
      importMutation.mutate(file);
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold">Import CSV</h1>
        <p className="text-gray-500 mt-1">Bulk import employees and allocations</p>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow p-6">
        <h2 className="text-lg font-semibold mb-4">CSV Format</h2>
        <div className="bg-gray-50 dark:bg-gray-700 rounded-lg p-4 font-mono text-sm overflow-x-auto">
          <div>name,email,department,role,joining_date,project_name,seat_number</div>
          <div className="text-gray-500">
            John Doe,john@ethara.ai,Engineering,Senior Engineer,2024-01-15,Talos,A1-10
          </div>
        </div>
        <ul className="mt-4 text-sm text-gray-600 dark:text-gray-400 space-y-1">
          <li>• Maximum file size: 5 MB</li>
          <li>• Date format: YYYY-MM-DD</li>
          <li>• seat_number is optional</li>
          <li>• Duplicate emails will be skipped</li>
        </ul>
      </div>

      <form onSubmit={handleSubmit} className="bg-white dark:bg-gray-800 rounded-xl shadow p-6">
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-2">Select CSV File</label>
            <input
              type="file"
              accept=".csv"
              onChange={(e) => {
                setFile(e.target.files?.[0] || null);
                setResult(null);
              }}
              className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-primary bg-white dark:bg-gray-700"
            />
          </div>

          {importMutation.error && (
            <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4 text-sm text-red-600 dark:text-red-400">
              {(importMutation.error as any).message}
            </div>
          )}

          {result && (
            <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
              <div className="font-semibold mb-2">Import Complete</div>
              <div className="space-y-1 text-sm">
                <div className="text-green-600 dark:text-green-400">
                  ✓ Imported: {result.imported} rows
                </div>
                <div className="text-amber-600 dark:text-amber-400">
                  ⚠ Skipped: {result.skipped} rows
                </div>
              </div>
              {result.errors.length > 0 && (
                <div className="mt-4">
                  <div className="font-semibold text-sm mb-2">Errors:</div>
                  <div className="max-h-48 overflow-auto space-y-1">
                    {result.errors.map((err, idx) => (
                      <div key={idx} className="text-xs text-red-600 dark:text-red-400">
                        {err}
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          <button
            type="submit"
            disabled={!file || importMutation.isPending}
            className="w-full bg-primary hover:bg-primary-hover text-white py-3 rounded-lg font-medium transition-default disabled:opacity-50"
          >
            {importMutation.isPending ? 'Importing...' : 'Import CSV'}
          </button>
        </div>
      </form>
    </div>
  );
}

